390	        if (value == null) {
391	            return "";
392	        }
393	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
394	    }
395	
396	    /**
397	     * Reduce an address to its canonical stored form: trim and collapse runs of
398	     * whitespace to a single space, upper-case, and expand common abbreviations
399	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
400	     * they appear as whole words. The result is what is stored, returned and used
401	     * for every household comparison; it is idempotent, so re-normalising an
402	     * already-normalised address leaves it unchanged.
403	     *
404	     * @param value the raw address (may be {@code null})
405	     * @return the normalised address, or the empty string if {@code value} is
406	     *         {@code null} or blank
