408	    public static String normalizeAddress(String value) {
409	        if (value == null) {
410	            return "";
411	        }
412	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
413	        if (collapsed.isEmpty()) {
414	            return "";
415	        }
416	        String[] tokens = collapsed.split(" ");
417	        for (int i = 0; i < tokens.length; i++) {
418	            tokens[i] = switch (tokens[i]) {
419	                case "ST" -> "STREET";
420	                case "RD" -> "ROAD";
421	                case "AVE" -> "AVENUE";
422	                default -> tokens[i];
423	            };
424	        }
425	        return String.join(" ", tokens);
426	    }
