204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
207	        HttpHeaders headers = new HttpHeaders();
208	        Visit visit = visitMapper.toVisit(visitFieldsDto);
209	        Pet pet = new Pet();
210	        pet.setId(petId);
211	        visit.setPet(pet);
212	        this.clinicService.saveVisit(visit);
213	        VisitDto visitDto = visitMapper.toVisitDto(visit);
214	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
215	            .buildAndExpand(visit.getId()).toUri());
216	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
217	    }
218	
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
223	        Owner owner = this.clinicService.findOwnerById(ownerId);
224	        if (owner != null) {
225	            Pet pet = owner.getPet(petId);
226	            if (pet != null) {
227	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
228	            }
229	        }
230	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	    }
232	
233	    /**
234	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
235	     * the canonical form each stored value must take: the address is trimmed,
236	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
237	     * telephone is converted to E.164, any email is lower-cased and a missing
238	     * registration date defaults to today. Field-level rejections are reported here
239	     * rather than inline in {@link #addOwner}, and normalisation runs before any
240	     * household comparison so those comparisons see the canonical values.
241	     *
242	     * @param owner the freshly-mapped owner to normalise
243	     * @return {@code true} if the fields are valid, or {@code false} if the address
244	     *         is blank after normalisation, the telephone cannot form a valid
245	     *         E.164 number, or a supplied registration date is later than the
246	     *         server date, in which case the request must be rejected with
247	     *         {@code 400 Bad Request}
248	     */
249	    private boolean normalizeNewOwner(Owner owner) {
250	        String address = Owner.normalizeAddress(owner.getAddress());
251	        if (address.isEmpty()) {
252	            return false;
253	        }
254	        owner.setAddress(address);
255	        String telephone = Telephones.toE164(owner.getTelephone());
256	        if (telephone == null) {
257	            return false;
258	        }
259	        owner.setTelephone(telephone);
260	        if (owner.getEmail() != null) {
261	            String email = owner.getEmail().toLowerCase();
262	            owner.setEmail(email);
263	            if (emailDomainIsBlocked(email)) {
264	                return false;
265	            }
266	        }
267	        if (!owner.postcodeValidForLocality()) {
268	            return false;
269	        }
270	        if (owner.getRegistrationDate() == null) {
271	            owner.setRegistrationDate(LocalDate.now());
272	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
273	            return false;
274	        }
275	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
276	        return true;
277	    }
278	
279	    /**
280	     * Email domains that identify disposable, throw-away mailboxes. An owner whose
281	     * email address is on one of these domains is rejected with {@code 400 Bad
282	     * Request} rather than created.
283	     */
284	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
285	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
286	
287	    /**
288	     * Whether the given (already lower-cased) email address belongs to a disposable
289	     * mailbox domain on the blocklist. The domain is the part after the final
290	     * {@code '@'}; an address without one is treated as having no blocked domain.
291	     *
292	     * @param email the owner's normalised (lower-cased) email address
293	     * @return {@code true} if the email's domain is on the disposable-domain blocklist
294	     */
295	    private static boolean emailDomainIsBlocked(String email) {
296	        int at = email.lastIndexOf('@');
297	        if (at < 0) {
298	            return false;
299	        }
300	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
301	    }
302	
303	    /**
304	     * Roll the given date forward to the next business day when it falls on a
305	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
306	     * weekday is returned unchanged. Applied to the effective registration date
307	     * (whether supplied in the request or defaulted to the server date) so that
308	     * every value derived from it uses the adjusted business day.
309	     *
310	     * @param date the effective registration date
311	     * @return the same date if it is a weekday, otherwise the next Monday
312	     */
313	    private static LocalDate rollToBusinessDay(LocalDate date) {
314	        switch (date.getDayOfWeek()) {
315	            case SATURDAY:
316	                return date.plusDays(2);
317	            case SUNDAY:
318	                return date.plusDays(1);
319	            default:
320	                return date;
321	        }
322	    }
323	
324	    /**
325	     * Find an existing owner that belongs to the same household as the given owner,
326	     * i.e. shares the same last name (compared case-insensitively with runs of
327	     * whitespace collapsed to a single space) and postcode, and so resolves to the same
328	     * deterministic {@code householdId}.
329	     *
330	     * @param owner the candidate owner being created
331	     * @return the matching existing owner, or empty if none exists
332	     */
333	    private Optional<Owner> findHouseholdMember(Owner owner) {
334	        return this.clinicService.findAllOwners().stream()
335	            .filter(existing -> existing.sameHouseholdAs(owner))
336	            .findFirst();
337	    }
338	
339	    /**
340	     * Assign the owner's computed-at-creation attributes in place: its customer code,
341	     * namesake count, membership number, bulk-signup warning and household size. Unlike
342	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
343	     * derived once here — from the owner's own (already normalised) fields and from the
344	     * wider owner population — and persisted with the owner. Run after normalisation,
345	     * household resolution and the identity-key check, so every value reflects the
346	     * owner's final field values and any household it has joined, and immediately before
347	     * the owner is saved.
348	     *
349	     * <p>Ordering matters: the customer code is assigned first because the membership
350	     * number is built from it.
351	     *
352	     * @param owner the candidate owner being created, after household resolution
353	     * @param declaredHouseholdMember whether this owner was created as a declared member
354	     *                                of an existing household (it shared an existing
355	     *                                owner's household and set {@code sharesHousehold}),
356	     *                                in which case it is not a suspected duplicate
357	     */
358	    private void assignDerivedAttributes(Owner owner, boolean declaredHouseholdMember) {
359	        owner.setCustomerCode(owner.computeCustomerCode());
360	        owner.setNamesakeCount(countNamesakes(owner));
361	        owner.setMembershipNumber(membershipNumber(owner));
362	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
363	        owner.setHouseholdSize(householdSize(owner));
364	        assignPossibleDuplicate(owner, declaredHouseholdMember);
365	    }
366	
367	    /**
368	     * Flag the candidate owner as a possible duplicate of an existing owner. A soft
369	     * match is an existing owner that shares this owner's last name (compared
370	     * case-insensitively) and postcode but carries a different (normalised) telephone.
371	     * When such a match exists the owner is still created, but with
372	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the matching
373	     * owner's id; otherwise {@code possibleDuplicate} is false and no match id is
374	     * recorded. The earliest-created matching owner (lowest id) is chosen so the result
375	     * is deterministic. Evaluated before the owner is saved, so only pre-existing owners
376	     * are considered.
377	     *
378	     * <p>A declared household member — one that shared an existing owner's household
379	     * (same last name and postcode) and was admitted because it set
380	     * {@code sharesHousehold} — is never flagged: a declared member is not a suspected
381	     * duplicate, so its {@code possibleDuplicate} is false with no match id.
382	     *
383	     * @param owner the candidate owner being created, after household resolution
384	     * @param declaredHouseholdMember whether the owner is a declared household member
385	     */
386	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
387	        if (declaredHouseholdMember) {
388	            owner.setPossibleDuplicate(false);
389	            owner.setPossibleDuplicateOf(null);
390	            return;
391	        }
392	        String lastName = normalizeName(owner.getLastName());
393	        String postcode = owner.getPostcode();
394	        String telephone = owner.getTelephone();
395	        Optional<Owner> match = this.clinicService.findAllOwners().stream()
396	            .filter(existing -> postcode != null && postcode.equals(existing.getPostcode())
397	                && normalizeName(existing.getLastName()).equals(lastName)
398	                && telephone != null && !telephone.equals(existing.getTelephone()))
399	            .min(Comparator.comparing(Owner::getId));
400	        if (match.isPresent()) {
401	            owner.setPossibleDuplicate(true);
402	            owner.setPossibleDuplicateOf(match.get().getId());
403	        } else {
404	            owner.setPossibleDuplicate(false);
405	            owner.setPossibleDuplicateOf(null);
406	        }
407	    }
408	
409	    /**
410	     * Count how many owners belong to the given owner's household once this create
411	     * completes: the owners that already share its deterministic {@code householdId}
412	     * (derived from last name and postcode) plus the owner being created. Evaluated
413	     * after the owner's {@code householdId} has been assigned. An owner whose
414	     * {@code householdId} matches no existing owner is a household of one.
415	     *
416	     * @param owner the candidate owner being created, after household resolution
417	     * @return the household member count after this create (at least {@code 1})
418	     */
419	    private int householdSize(Owner owner) {
420	        String householdId = owner.getHouseholdId();
421	        if (householdId == null) {
422	            return 1;
423	        }
424	        long existing = this.clinicService.findAllOwners().stream()
425	            .filter(other -> householdId.equals(other.getHouseholdId()))
426	            .count();
427	        return (int) existing + 1;
428	    }
429	
430	    /**
431	     * Count the existing owners that share the given owner's first and last name,
432	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
433	     * before the new owner is saved, so the result reflects only owners that
434	     * already existed at creation time.
435	     *
436	     * @param owner the candidate owner being created
437	     * @return the number of existing namesakes
438	     */
439	    private int countNamesakes(Owner owner) {
440	        String firstName = normalizeName(owner.getFirstName());
441	        String lastName = normalizeName(owner.getLastName());
442	        return (int) this.clinicService.findAllOwners().stream()
443	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
444	                && normalizeName(existing.getLastName()).equals(lastName))
445	            .count();
446	    }
447	
448	    private static String normalizeName(String value) {
449	        return value == null ? "" : value.trim().toLowerCase();
450	    }
451	
452	    /**
453	     * Determine whether the given city has already reached its owner capacity, i.e.
454	     * it already contains 50 or more existing owners (compared case-insensitively
455	     * with surrounding whitespace trimmed). A new owner may not be created in a city
456	     * that is at capacity.
457	     *
458	     * @param city the candidate owner's city
459	     * @return {@code true} if the city already holds 50 or more owners
460	     */
461	    private boolean cityIsAtCapacity(String city) {
462	        String normalizedCity = normalizeName(city);
463	        long count = this.clinicService.findAllOwners().stream()
464	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
465	            .count();
466	        return count >= 50;
467	    }
468	
469	    /**
470	     * Determine whether the daily owner-creation limit has already been reached, i.e.
471	     * 100 or more owners already carry the given registration date. A new owner may
472	     * not be created once that day's cap is reached.
473	     *
474	     * @param registrationDate the registration date the new owner would be created with
475	     * @return {@code true} if 100 or more existing owners share that registration date
476	     */
477	    private boolean dailyLimitReached(LocalDate registrationDate) {
478	        long count = this.clinicService.findAllOwners().stream()
479	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
480	            .count();
481	        return count >= 100;
482	    }
483	
484	    /**
485	     * Determine whether more than 80 owners have already been created for the given
486	     * registration date, i.e. strictly more than 80 existing owners carry that date.
487	     * Evaluated before the new owner is saved, so it reflects only owners that
488	     * already existed at creation time.
489	     *
490	     * @param registrationDate the registration date the new owner would be created with
491	     * @return {@code true} if more than 80 existing owners share that registration date
492	     */
493	    private boolean bulkSignupWarning(LocalDate registrationDate) {
494	        long count = this.clinicService.findAllOwners().stream()
495	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
496	            .count();
497	        return count > 80;
498	    }
499	
500	    /**
501	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
502	     * one place so it stays in step with the owner's identity: it reports the assigned
503	     * customer code alongside the owner's id, registration date and membership level.
504	     *
505	     * @param owner the owner that has just been created and saved
506	     */
507	    private void auditOwnerCreated(Owner owner) {
508	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
509	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
510	    }
511	
512	    /**
513	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
514	     * where {@code <customerCode>} is the owner's already-assigned customer code and
515	     * YY is the last two digits of the registration date's year (e.g.
516	     * {@code NSW-9F86D081-M26}). Evaluated after the customer code and registration date
517	     * have been set.
518	     *
519	     * @param owner the owner being created, with customer code and registration date
520	     *              already assigned
521	     * @return the assigned membership number
522	     */
523	    private String membershipNumber(Owner owner) {
524	        int yy = owner.getRegistrationDate().getYear() % 100;
525	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
526	    }
527	}
